//! What a TVFS link actually shows. Reader, audio player and batch pages are static HTML
//! generated by the server (`upload.js`, `audioPlayer.js`, `protectedShare.js`); the real file
//! URL and the page data sit in JSON literals inside them (`fetch(<url>)`, `window.TVFS_PLAYER = {..}`
//! or the older `var AUDIO_URL = <url>`, `const files = [...]`), which is what is read here. Nothing on the server changes for this.

use std::path::Path;

use serde::Deserialize;
use url::Url;

use crate::client::Client;
use crate::error::{Error, Result};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ContentKind {
    Video,
    Audio,
    Text,
    Markdown,
    Image,
    /// Anything else: offered for download.
    File,
}

/// One file to show in a native viewer.
#[derive(Debug, Clone, PartialEq)]
pub struct Content {
    /// Absolute URL of the file itself (not of a page).
    pub url: String,
    /// Original file name (what the user sees and what a download is saved as).
    pub name: String,
    pub kind: ContentKind,
    /// Needs the `tvfs_token` session cookie ("TVFS Users Only" shares).
    pub protected: bool,
    /// The link that was opened (a reader / player page or the file itself), for "Copy link".
    pub page: String,
}

#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct BatchFile {
    pub url: String,
    pub name: String,
    #[serde(default)]
    pub styled: String,
}

/// A batch landing page (`/files/batch/<id>.html`).
#[derive(Debug, Clone, PartialEq)]
pub struct BatchPage {
    pub id: String,
    pub files: Vec<BatchFile>,
    pub page_link: String,
    pub page_styled: String,
    /// "3 files • 12.4 MB" exactly as the page shows it.
    pub subtitle: String,
    /// "These files expire on October 30, 2026"
    pub expire_note: String,
    /// Size text of each file ("1.2 MB"), in the order of `files`.
    pub sizes: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ShareFile {
    pub index: u32,
    pub relative_path: String,
    #[serde(default)]
    pub size: u64,
    #[serde(default)]
    pub category: Option<String>,
    #[serde(default)]
    pub tool_link: Option<String>,
}

/// A "TVFS Users Only" share (`/files/protected/pages/<id>.html`, `GET /api/protected/<id>/meta`).
#[derive(Debug, Clone, PartialEq, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ShareMeta {
    pub id: String,
    pub files: Vec<ShareFile>,
    #[serde(default)]
    pub total_size: u64,
    #[serde(default)]
    pub expires_at: i64,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Resolved {
    Content(Content),
    Batch(BatchPage),
    Share { meta: ShareMeta, page: String },
    /// Not something the app shows (e.g. the TVFS home page): open it in the browser.
    Browser(String),
}

const VIDEO_EXT: &[&str] = &[
    "mp4", "m4v", "mov", "mkv", "webm", "avi", "wmv", "flv", "ts", "m2ts", "mts", "mpg", "mpeg", "3gp", "ogv", "vob", "hevc", "h264",
];
const AUDIO_EXT: &[&str] = &[
    "mp3", "flac", "wav", "ogg", "oga", "opus", "m4a", "aac", "wma", "alac", "aif", "aiff", "ape", "wv", "dsf", "dff", "mka",
];
const IMAGE_EXT: &[&str] = &["jpg", "jpeg", "png", "gif", "webp", "bmp", "avif", "ico", "tif", "tiff", "jfif"];
const MD_EXT: &[&str] = &["md", "markdown", "mdown", "mkd"];
const TEXT_EXT: &[&str] = &[
    "txt", "log", "nfo", "ini", "cfg", "conf", "csv", "tsv", "json", "xml", "yaml", "yml", "toml", "srt", "vtt", "ass", "ssa", "lrc",
];

/// Every extension a native viewer opens (the "Use TVFS tools locally" file dialog).
pub fn viewer_extensions() -> Vec<&'static str> {
    [VIDEO_EXT, AUDIO_EXT, IMAGE_EXT, MD_EXT, TEXT_EXT].concat()
}

impl Content {
    /// A file on this computer ("Use TVFS tools locally"): a `file://` URL, nothing goes to the server.
    pub fn local(path: &Path) -> Option<Content> {
        let url = Url::from_file_path(path).ok()?;
        let name = path.file_name()?.to_string_lossy().into_owned();
        Some(Content { url: url.to_string(), kind: kind_from_name(&name), name, protected: false, page: String::new() })
    }

    /// The path of a local file (`Content::local`), `None` for a TVFS file.
    pub fn local_path(&self) -> Option<std::path::PathBuf> {
        Url::parse(&self.url).ok().filter(|u| u.scheme() == "file")?.to_file_path().ok()
    }
}

/// The kind of a file from its name (extension).
pub fn kind_from_name(name: &str) -> ContentKind {
    let ext = Path::new(name).extension().and_then(|e| e.to_str()).unwrap_or("").to_ascii_lowercase();
    let is = |list: &[&str]| list.contains(&ext.as_str());
    if is(VIDEO_EXT) {
        ContentKind::Video
    } else if is(AUDIO_EXT) {
        ContentKind::Audio
    } else if is(IMAGE_EXT) {
        ContentKind::Image
    } else if is(MD_EXT) {
        ContentKind::Markdown
    } else if is(TEXT_EXT) {
        ContentKind::Text
    } else {
        ContentKind::File
    }
}

/// Undo the server's `escapeHtml` (title text).
fn unescape_html(s: &str) -> String {
    s.replace("&lt;", "<").replace("&gt;", ">").replace("&quot;", "\"").replace("&#x27;", "'").replace("&#39;", "'").replace("&amp;", "&")
}

/// The first JSON value that starts right after `marker` (whitespace allowed).
fn json_after<T: serde::de::DeserializeOwned>(html: &str, marker: &str) -> Option<T> {
    let start = html.find(marker)? + marker.len();
    let rest = html[start..].trim_start();
    serde_json::Deserializer::from_str(rest).into_iter::<T>().next()?.ok()
}

/// `<title>NAME — TVFS ...</title>` -> (NAME, the suffix after the dash).
fn page_title(html: &str) -> Option<(String, String)> {
    let a = html.find("<title>")? + "<title>".len();
    let b = a + html[a..].find("</title>")?;
    let title = &html[a..b];
    let (name, suffix) = title.rsplit_once(" — ")?;
    Some((unescape_html(name.trim()), suffix.trim().to_owned()))
}

fn last_segment(url: &str) -> String {
    let path = url.split(['?', '#']).next().unwrap_or(url);
    let seg = path.rsplit('/').next().unwrap_or("");
    percent_encoding::percent_decode_str(seg).decode_utf8_lossy().into_owned()
}

/// A text / Markdown reader page (public `_tvfsreader.html` or a protected `_reader.html`).
pub fn parse_reader_page(html: &str, page: &str) -> Option<Content> {
    let (name, suffix) = page_title(html)?;
    if !suffix.contains("Reader") {
        return None;
    }
    let url: String = json_after(html, "fetch(")?;
    // the MD readers load marked.js; plain-text readers do not
    let markdown = suffix.contains("MD Reader") || html.contains("marked.min.js") || kind_from_name(&name) == ContentKind::Markdown;
    Some(Content {
        protected: url.contains("/api/protected/"),
        url,
        name,
        kind: if markdown { ContentKind::Markdown } else { ContentKind::Text },
        page: page.to_owned(),
    })
}

/// Track data of an audio player page: `window.TVFS_PLAYER` (pages since 2026-10-31; `lufs` since the
/// loudness normalization) or the older `var AUDIO_URL` / `var TRACK_BPM` globals.
#[derive(Debug, Clone, Default, PartialEq, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AudioPageData {
    pub audio_url: String,
    #[serde(default)]
    pub bpm: Option<f64>,
    /// Integrated loudness measured by the server (EBU R128).
    #[serde(default)]
    pub lufs: Option<f64>,
}

pub fn parse_audio_data(html: &str) -> Option<AudioPageData> {
    if let Some(d) = json_after::<AudioPageData>(html, "window.TVFS_PLAYER =") {
        return Some(d);
    }
    let audio_url: String = json_after(html, "var AUDIO_URL =")?;
    // a bare number before `;` (serde's stream reader rejects a number glued to the `;`)
    let bpm = html.find("var TRACK_BPM =").and_then(|i| {
        let rest = &html[i + "var TRACK_BPM =".len()..];
        rest[..rest.find([';', '\n']).unwrap_or(rest.len())].trim().parse::<f64>().ok()
    });
    Some(AudioPageData { audio_url, bpm, lufs: None })
}

/// An audio player page (`/files/players/*_player.html`, protected `tools/*_player.html`).
pub fn parse_audio_page(html: &str, page: &str) -> Option<Content> {
    let url = parse_audio_data(html)?.audio_url;
    let name = page_title(html).map(|t| t.0).unwrap_or_else(|| last_segment(&url));
    Some(Content { protected: url.contains("/api/protected/"), url, name, kind: ContentKind::Audio, page: page.to_owned() })
}

/// Text between `<p class="{class}">` and `</p>` with the HTML entities undone.
fn paragraph(html: &str, class: &str) -> String {
    let marker = format!("class=\"{class}\">");
    html.find(&marker)
        .and_then(|a| {
            let a = a + marker.len();
            html[a..].find("</p>").map(|b| unescape_html(html[a..a + b].trim()))
        })
        .unwrap_or_default()
}

pub fn parse_batch_page(html: &str) -> Option<BatchPage> {
    let files: Vec<BatchFile> = json_after(html, "const files =")?;
    Some(BatchPage {
        id: json_after(html, "const batchId =").unwrap_or_default(),
        page_link: json_after(html, "const pageLink =").unwrap_or_default(),
        page_styled: json_after(html, "const pageStyled =").unwrap_or_default(),
        subtitle: paragraph(html, "subtitle"),
        expire_note: paragraph(html, "expire-note"),
        sizes: html
            .split("<span class=\"file-size\">")
            .skip(1)
            .filter_map(|s| s.split_once("</span>").map(|(v, _)| unescape_html(v.trim())))
            .collect(),
        files,
    })
}

fn file_content(url: &Url, page: &str, protected: bool, name: String) -> Content {
    Content { url: url.to_string(), kind: kind_from_name(&name), name, protected, page: page.to_owned() }
}

/// Work out what `link` shows. Pages are downloaded (with the session cookie) and read.
pub async fn resolve(client: &Client, link: &Url) -> Result<Resolved> {
    let page = link.as_str();
    let segments: Vec<String> = link
        .path_segments()
        .map(|s| s.filter(|s| !s.is_empty()).map(|s| percent_encoding::percent_decode_str(s).decode_utf8_lossy().into_owned()).collect())
        .unwrap_or_default();
    let seg: Vec<&str> = segments.iter().map(String::as_str).collect();
    let html_page = seg.last().is_some_and(|s| s.to_ascii_lowercase().ends_with(".html"));
    match seg.as_slice() {
        ["files", "batch", ..] if html_page => {
            let html = fetch_page(client, link).await?;
            parse_batch_page(&html).map(Resolved::Batch).ok_or_else(|| not_understood("batch page"))
        }
        ["files", "protected", "pages", file] => {
            let id = file.trim_end_matches(".html");
            Ok(Resolved::Share { meta: share_meta(client, id).await?, page: page.to_owned() })
        }
        ["files", "protected", "tools", _] | ["files", "players", ..] | ["files", "text", ..] if html_page => {
            let html = fetch_page(client, link).await?;
            parse_audio_page(&html, page)
                .or_else(|| parse_reader_page(&html, page))
                .map(Resolved::Content)
                .ok_or_else(|| not_understood("player page"))
        }
        ["api", "protected", id, "file", index] => {
            let meta = share_meta(client, id).await?;
            let index: u32 = index.parse().map_err(|_| not_understood("share file link"))?;
            let f = meta.files.iter().find(|f| f.index == index).ok_or_else(|| not_understood("share file link"))?;
            Ok(Resolved::Content(file_content(link, page, true, last_segment(&f.relative_path))))
        }
        ["files", _, .., name] if !html_page => Ok(Resolved::Content(file_content(link, page, false, (*name).to_owned()))),
        _ => Ok(Resolved::Browser(page.to_owned())),
    }
}

fn not_understood(what: &str) -> Error {
    Error::Server { status: 0, message: format!("could not read this {what}") }
}

async fn fetch_page(client: &Client, link: &Url) -> Result<String> {
    let bytes = client.fetch_bytes(link.as_str(), 8 * 1024 * 1024).await?;
    Ok(String::from_utf8_lossy(&bytes).into_owned())
}

/// `GET /api/protected/<id>/meta` (no login needed; the files themselves need one).
pub async fn share_meta(client: &Client, id: &str) -> Result<ShareMeta> {
    let url = client.base().join(&format!("api/protected/{}/meta", crate::client::path_segment(id)))?;
    let bytes = client.fetch_bytes(url.as_str(), 4 * 1024 * 1024).await?;
    serde_json::from_slice(&bytes).map_err(|e| Error::Server { status: 0, message: format!("bad share data: {e}") })
}

impl ShareMeta {
    /// The content of file `index` (served only to logged-in TVFS users).
    pub fn content(&self, base: &Url, file: &ShareFile) -> Content {
        let url = base.join(&format!("api/protected/{}/file/{}", crate::client::path_segment(&self.id), file.index)).map(|u| u.to_string()).unwrap_or_default();
        let name = last_segment(&file.relative_path);
        Content { kind: kind_from_name(&name), name, protected: true, page: url.clone(), url }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const MD_PAGE: &str = r#"<!DOCTYPE html><html><head><title>notes &amp; ideas.md — TVFS MD Reader</title></head><body>
<script src="https://cdn.jsdelivr.net/npm/marked@9/marked.min.js"></script>
<script>
fetch("https://files.tomasekvalla.cz/files/text/notes_123.md")
.then(function(r){})
</script></body></html>"#;

    const PROTECTED_TXT: &str = r#"<html><head><title>log.txt — TVFS Users Only Reader</title></head><body><script>
  fetch("https://files.tomasekvalla.cz/api/protected/ab12/file/0", { credentials: 'include' })
var GATE_API = '/api/protected/' + "ab12";
</script></body></html>"#;

    const AUDIO_PAGE: &str = r#"<html><head><title>Song <1>.flac — TVFS Audio Player</title></head><body>
<audio id="audio" src="https://files.tomasekvalla.cz/files/audio/song.flac" preload="metadata"></audio>
<script>
var AUDIO_URL = "https://files.tomasekvalla.cz/files/audio/song.flac";
var TRACK_BPM = 120;
</script></body></html>"#;

    // the template since 2026-10-31 (`buildPlayerHtml`, `safeScriptJson` escapes < and >)
    const AUDIO_PAGE_V2: &str = r#"<html><head><title>Stars &amp; Night.flac — TVFS Audio Player</title></head><body>
<audio id="audio" preload="metadata"></audio>
<script type="text/plain" id="workletSrc">var AUDIO_URL = "decoy";</script>
<script>window.TVFS_PLAYER = {"audioUrl":"https://files.tomasekvalla.cz/files/audio/stars_<1>.flac","bpm":128,"lufs":-4.7,"gated":false,"icons":{"play":"<svg>"}};</script>
</body></html>"#;

    const BATCH_PAGE: &str = r#"<html><body><div class="container">
    <h1><span>TomasekValla</span> Shared Files</h1>
    <p class="subtitle">2 files • 3.5 MB</p>
    <div class="file-row"><a href="x" class="file-name">a.png</a>
    <span class="file-size">1.5 MB</span></div>
    <div class="file-row"><a href="y" class="file-name">b.mkv</a>
    <span class="file-size">2 MB</span></div>
    <p class="expire-note">These files expire on October 30, 2026</p>
    </div>
    <script>
    const files = [{"url":"https://files.tomasekvalla.cz/files/pictures/a.png","name":"a.png","styled":"[🖼️ a.png](https://files.tomasekvalla.cz/files/pictures/a.png)"},{"url":"https://files.tomasekvalla.cz/files/download/b.mkv","name":"b <1>.mkv","styled":"[x](y)"}];
    const pageLink = "https://files.tomasekvalla.cz/files/batch/batch_1_ab.html";
    const pageStyled = "[2 Files (3.5 MB) - TomasekValla Filestream System](https://files.tomasekvalla.cz/files/batch/batch_1_ab.html)";
    const batchId = "batch_1_ab";
    </script></body></html>"#;

    #[test]
    fn kinds_by_extension() {
        assert_eq!(kind_from_name("a.MKV"), ContentKind::Video);
        assert_eq!(kind_from_name("a.flac"), ContentKind::Audio);
        assert_eq!(kind_from_name("a.webp"), ContentKind::Image);
        assert_eq!(kind_from_name("README.md"), ContentKind::Markdown);
        assert_eq!(kind_from_name("a.txt"), ContentKind::Text);
        assert_eq!(kind_from_name("a.zip"), ContentKind::File);
        assert_eq!(kind_from_name("noext"), ContentKind::File);
    }

    #[test]
    fn md_reader_page() {
        let c = parse_reader_page(MD_PAGE, "p").unwrap();
        assert_eq!(c.url, "https://files.tomasekvalla.cz/files/text/notes_123.md");
        assert_eq!(c.name, "notes & ideas.md");
        assert_eq!(c.kind, ContentKind::Markdown);
        assert!(!c.protected);
        assert!(parse_audio_page(MD_PAGE, "p").is_none());
    }

    #[test]
    fn protected_text_reader_page() {
        let c = parse_reader_page(PROTECTED_TXT, "p").unwrap();
        assert_eq!(c.url, "https://files.tomasekvalla.cz/api/protected/ab12/file/0");
        assert_eq!(c.kind, ContentKind::Text);
        assert!(c.protected);
    }

    #[test]
    fn audio_page() {
        let c = parse_audio_page(AUDIO_PAGE, "p").unwrap();
        assert_eq!(c.url, "https://files.tomasekvalla.cz/files/audio/song.flac");
        assert_eq!(c.kind, ContentKind::Audio);
        assert!(parse_reader_page(AUDIO_PAGE, "p").is_none());
    }

    #[test]
    fn audio_page_v2() {
        let d = parse_audio_data(AUDIO_PAGE_V2).unwrap();
        assert_eq!(d.audio_url, "https://files.tomasekvalla.cz/files/audio/stars_<1>.flac");
        assert_eq!(d.bpm, Some(128.0));
        assert_eq!(d.lufs, Some(-4.7));
        let c = parse_audio_page(AUDIO_PAGE_V2, "p").unwrap();
        assert_eq!(c.name, "Stars & Night.flac");
        assert_eq!(c.kind, ContentKind::Audio);
        // old pages: no loudness, BPM from the global
        let old = parse_audio_data(AUDIO_PAGE).unwrap();
        assert_eq!((old.bpm, old.lufs), (Some(120.0), None));
    }

    #[test]
    fn batch_page() {
        let b = parse_batch_page(BATCH_PAGE).unwrap();
        assert_eq!(b.id, "batch_1_ab");
        assert_eq!(b.files.len(), 2);
        assert_eq!(b.files[1].name, "b <1>.mkv");
        assert_eq!(b.subtitle, "2 files • 3.5 MB");
        assert_eq!(b.sizes, vec!["1.5 MB".to_string(), "2 MB".to_string()]);
        assert_eq!(b.expire_note, "These files expire on October 30, 2026");
        assert!(b.page_styled.starts_with("[2 Files"));
    }

    #[test]
    fn share_content_link() {
        let meta = ShareMeta {
            id: "ab12".into(),
            files: vec![ShareFile { index: 1, relative_path: "folder/clip.mp4".into(), size: 5, category: None, tool_link: None }],
            total_size: 5,
            expires_at: 0,
        };
        let c = meta.content(&Url::parse("https://files.tomasekvalla.cz").unwrap(), &meta.files[0]);
        assert_eq!(c.url, "https://files.tomasekvalla.cz/api/protected/ab12/file/1");
        assert_eq!(c.name, "clip.mp4");
        assert_eq!(c.kind, ContentKind::Video);
        assert!(c.protected);
    }
}
